import { Router } from '@angular/router';
import { inject } from '@angular/core';
import { AuthService } from '../services/auth.service';
/**
 * Portal guard: allows access to portal routes when the user is logged in
 * AND is either an Admin or Faculty (INSTRUCTOR).
 */
export const adminGuard = () => {
  const auth = inject(AuthService);
  const router = inject(Router);
  if (auth.isLoggedIn() && auth.isPortalUser) {
    return true;
  }
  router.navigate(['/login']);
  return false;
};
/**
 * Super-admin-only guard: blocks everyone except the Super Admin (ADMIN role)
 * from routes exclusive to the platform owner (Organizations, Subscriptions).
 */
export const adminOnlyGuard = () => {
  const auth = inject(AuthService);
  const router = inject(Router);
  if (auth.isLoggedIn() && auth.isAdmin) {
    return true;
  }
  router.navigate(['/']);
  return false;
};
/**
 * Org-admin-or-above guard: allows Super Admin and Organization Admin
 * (INSTITUTE_ADMIN) into routes like Faculty, Payments, Settings, blocking Faculty/Students.
 */
export const orgAdminGuard = () => {
  const auth = inject(AuthService);
  const router = inject(Router);
  if (auth.isLoggedIn() && (auth.isAdmin || auth.isOrgAdmin)) {
    return true;
  }
  router.navigate(['/']);
  return false;
};
